document.addEventListener(`DOMContentLoaded`,()=>{try{let e=localStorage.getItem(`i18n-cache-lang`),t=localStorage.getItem(`i18n-cache-messages`);if(t&&e){let e=JSON.parse(t);document.querySelectorAll(`[data-i18n]`).forEach(t=>{let n=t.getAttribute(`data-i18n`);if(e[n]&&e[n].message&&!t.textContent){let r=e[n].message;r.includes(`$`)||(t.textContent=r)}}),document.querySelectorAll(`[data-i18n-title]`).forEach(t=>{let n=t.getAttribute(`data-i18n-title`);if(e[n]&&!t.title){let r=e[n].description||e[n].message||n;r.includes(`$`)||(t.title=r)}}),document.querySelectorAll(`[data-i18n-placeholder]`).forEach(t=>{let n=t.getAttribute(`data-i18n-placeholder`);e[n]&&e[n].message&&!t.getAttribute(`placeholder`)&&(t.tagName===`DIV`&&t.isContentEditable?t.setAttribute(`data-i18n-placeholder`,e[n].message):t.setAttribute(`placeholder`,e[n].message))}),document.querySelectorAll(`[data-i18n-aria-label]`).forEach(t=>{let n=t.getAttribute(`data-i18n-aria-label`);e[n]&&e[n].message&&!t.getAttribute(`aria-label`)&&t.setAttribute(`aria-label`,e[n].message)})}}catch(e){console.error(`[i18n-init.js] Error aplicando traducciones cacheadas:`,e)}});